    task: state.current.task,
    status: state.current.terminal_status || 'incomplete',
    reason: state.current.terminal_reason || 'NO_TERMINAL_REASON',
    refinement_iterations: state.current.refinement_iteration,
    suite_id: state.current.suite_id,
    timeline: state.current.timeline,
    artifacts: result,
  });
  state.run_index += 1;
  if (state.run_index >= state.run_specs.length) {
    choose('complete');
  } else {
    const next = state.run_specs[state.run_index];
    state.current = {
      ...next,
      run_id: null,
      suite_id: null,
      refinement_iteration: 0,
      generation_purpose: 'initial',
      has_transformation: false,
      timeline: [],
      terminal_status: null,
      terminal_reason: null,
    };
    state.completed_action = null;
    state.last_result = null;
    choose('create_run');
  }
