  // `Prompting_ETL_*_grammar.json` reads `..._few_shots_AND_grammar.json` back as
  // well. A workflow declares its strategy as the longest strategy name its
  // identity ends with; matching that exactly keeps the executed prompting
  // strategy equal to the one recorded in the run configuration.
  const strategyNames = ['only_prompt', 'few_shot', 'grammar', 'few_shots_AND_grammar'];
  const declaredStrategy = (identity) => {
    const name = String(identity || '').replace(/\.json$/, '');
    let declared = null;
    for (const known of strategyNames) {
      if (!name.endsWith(`_${known}`)) continue;
      if (!declared || known.length > declared.length) declared = known;
    }
    return declared;
  };
  const selectorIsGlob = String(state.subworkflow_path || '').includes('*');
  if (selectorIsGlob && !strategyNames.includes(strategy)) {
    throw new Error(`A variant selector requires a supported strategy: ${state.subworkflow_path}`);
  }

