    try {
      candidate = JSON.parse(raw);
    } catch (error) {
      throw new Error(`Invalid subworkflow JSON at ${state.subworkflow_path}: ${error.message}`);
    }
    if (
      !Array.isArray(candidate.nodes)
      || !candidate.connections
      || !candidate.nodes.some((node) => node.type === expectedType)
    ) continue;
    const identity = item.binary?.data?.fileName || item.json.fileName || candidate.name;
    if (selectorIsGlob && declaredStrategy(identity) !== strategy) continue;
    candidates.push({ identity: String(identity || ''), workflow: candidate });
  }
